import { isProxy, Log, objectCountUtils, proxyUtils, storeUtils, toParentWatchProxy, toProxy, watchUpdates } from '@fanfanlo';
import _ from 'lodash';
import { ulid } from 'ulid';
import store from 'store2';
import { createDefaultProject } from '../entities/IProject';
import { createDefaultTriggerActionGroup } from '../entities/ITriggerActionGroup';
import { IProject } from '../entities/IProject';
import { createDefaultProjectSettings, IProjectSettings } from '../types/IProjectSettings';
import { syncProject } from '../utils/projectMerge';

export const s = storeUtils.namespace('project-v2');
const listName = 'list';
const draftName = 'draft';
const projectSettingsMapName = "projectSettings"

const fileLog = new Log(false, 'project-v2-interface-storage');
// fileLog.pause = true;
// fileLog.childrenPaused = true;

function loadProjectList(): IProject[] {
  const fnLog = fileLog.sub(false, 'loadProjectList_fn');
  fnLog.pause = true;
  let list = s.read(listName) as IProject[];
  fnLog.log('list=', list);
  if (!_.isArray(list) || !list) list = [];
  const res = prepareProjectList(list);
  return res;
}

function loadDraft(): IProject[] {
  const fnLog = fileLog.sub(false, 'loadDraft_fn');
  fnLog.pause = true;
  let list = s.read(draftName) as IProject[];
  fnLog.log('list=', list);
  if (!_.isArray(list) || !list) list = [];
  const res = prepareProjectList(list);
  return res;
}

function loadProjectSettingsMap():Record<string, IProjectSettings>{
  const fnLog = fileLog.sub(false, 'loadProjectSettingsMap_fn');
  // fnLog.pause = true;
  let map:Record<string, IProjectSettings> = s.read(projectSettingsMapName) as Record<string, IProjectSettings>
  fnLog.log('map=', map)
  fnLog.log('map json =', JSON.stringify(map), 'ismap bool=', _.isMap(map))
  if(!map || !_.isObject(map)) map = {}
  return toProxy(map);
}

function prepareProjectList(list: IProject[]) {
  const fnLog = fileLog.sub(false, 'prepareProjectList_fn');
  fnLog.pause = true;
  return list.map(p => {
    fnLog.log(`[prepareProjectList] 处理项目, ulid=${p.ulid}`);

    // 确保 children 数组存在
    if (!p.children) {
      p.children = [];
      fnLog.log(`[prepareProjectList] 初始化 children 数组`);
    }

    // 确保 children[0] 存在
    if (!p.children[0]) {
      
        // 创建默认值
        const triggerActionGroup = createDefaultTriggerActionGroup();
        p.children[0] = triggerActionGroup;
    }

    const merged = _.merge(createDefaultProject(), p);
    if (!merged.ulid) {
      merged.ulid = ulid();
      fnLog.log(`[数据迁移] 为项目生成 ulid: ${merged.ulid}`);
    }
    return merged;
  });
}

const list: IProject[] = toParentWatchProxy(loadProjectList());
const draft: IProject[] = toParentWatchProxy(loadDraft());

// const projectSettingsMap:Record<string, IProjectSettings> = toParentWatchProxy(loadProjectSettingsMap());
const _projectSettingsMap = loadProjectSettingsMap();
console.log('_projectSettingsMap file init', _projectSettingsMap)
const projectSettingsMap:Record<string, IProjectSettings> = toProxy(_projectSettingsMap);
toParentWatchProxy(projectSettingsMap)
console.log('projectSettingsMap file init', projectSettingsMap,'ssssssss', JSON.stringify(projectSettingsMap))
